@Repository
public class InventoryRepository {
    @PersistenceContext
    private EntityManager em;

    @Transactional
    public Inventory findByIdWithRowLock(Long id) {
        // Acquires a pessimistic row-level write lock (SELECT ... FOR UPDATE)
        return em.find(Inventory.class, id, LockModeType.PESSIMISTIC_WRITE);
    }

    @Transactional
    public boolean acquireAdvisoryLock(long lockKey) {
        // Native PostgreSQL advisory lock query
        Query query = em.createNativeQuery("SELECT pg_try_advisory_xact_lock(:key)");
        query.setParameter("key", lockKey);
        return (Boolean) query.getSingleResult();
    }
}
